"""Bounded result documents generated by the trusted finalizer."""
from hashlib import sha256
import json
from uuid import UUID

from fastapi import HTTPException, Response

NAME = 'result.json'
SAFE_HEADERS = {
    'Cache-Control': 'no-store',
    'X-Content-Type-Options': 'nosniff',
    'Content-Security-Policy': "default-src 'none'; sandbox",
}


def result_document(claim, commit_sha, state, reason, exit_code, elapsed_ms, provenance):
    return (json.dumps({
        'run_id': str(claim.run_id), 'attempt_id': str(claim.attempt_id), 'attempt_no': claim.attempt_no,
        'commit_sha': commit_sha, 'state': state, 'reason': reason, 'exit_code': exit_code,
        'execution_ms': elapsed_ms, 'source': provenance,
    }, sort_keys=True, separators=(',', ':')) + '\n').encode('utf-8')


def store(conn, attempt_id: UUID, payload: bytes):
    conn.execute(
        'INSERT INTO artifacts(attempt_id,relative_name,storage_key,size_bytes,sha256,payload) '
        'VALUES (%s,%s,%s,%s,%s,%s)',
        (attempt_id, NAME, f'{attempt_id}/{NAME}', len(payload), sha256(payload).hexdigest(), payload),
    )


def has_result(conn, attempt_id: UUID) -> bool:
    return conn.execute(
        'SELECT 1 FROM artifacts WHERE attempt_id=%s AND relative_name=%s AND payload IS NOT NULL',
        (attempt_id, NAME),
    ).fetchone() is not None


def matches(conn, attempt_id: UUID, payload: bytes) -> bool:
    row = conn.execute('SELECT payload FROM artifacts WHERE attempt_id=%s AND relative_name=%s',
                       (attempt_id, NAME)).fetchone()
    return row is not None and row['payload'] == payload


def download(factory, run_id: UUID, attempt_id: UUID) -> Response:
    with factory() as conn:
        row = conn.execute(
            'SELECT r.completed_attempt_id, r.state, a.state AS attempt_state, f.payload, f.sha256 '
            'FROM runs r LEFT JOIN attempts a ON a.id=r.completed_attempt_id AND a.run_id=r.id '
            'LEFT JOIN artifacts f ON a.id=f.attempt_id AND f.relative_name=%s '
            'WHERE r.id=%s',
            (NAME, run_id),
        ).fetchone()
    if row is None:
        raise HTTPException(404, 'run not found', headers=SAFE_HEADERS)
    if (row['completed_attempt_id'] != attempt_id or row['state'] != row['attempt_state']
            or row['state'] not in ('succeeded', 'failed', 'timed_out')):
        raise HTTPException(409, 'official attempt changed or not finalized', headers=SAFE_HEADERS)
    if row['payload'] is None:
        raise HTTPException(404, 'result artifact unavailable', headers=SAFE_HEADERS)
    return Response(row['payload'], media_type='application/json', headers=SAFE_HEADERS | {
        'Content-Disposition': f'attachment; filename="{NAME}"', 'X-Artifact-SHA256': row['sha256'],
    })
